using Microsoft.AspNetCore.Mvc;

namespace Acme.Controllers;

public sealed record CreateUserRequest(string Email, string Name, int Age);

[ApiController]
[Route("users")]
public sealed class UsersController(UserService users) : ControllerBase
{
    [HttpPost]
    public async Task<IActionResult> Create(CreateUserRequest request, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(request.Email) || !request.Email.Contains('@'))
        {
            return BadRequest("email is invalid");
        }
        if (string.IsNullOrWhiteSpace(request.Name) || request.Name.Length > 50)
        {
            return BadRequest("name is invalid");
        }
        if (request.Age < 0 || request.Age > 150)
        {
            return BadRequest("age is invalid");
        }

        var id = await users.CreateAsync(request, ct);
        return Created($"/users/{id}", new { id });
    }
}

