using FluentValidation;

namespace Acme.Controllers;

public sealed class CreateUserRequestValidator : AbstractValidator<CreateUserRequest>
{
    public CreateUserRequestValidator()
    {
        RuleFor(x => x.Email).NotEmpty().EmailAddress();
        RuleFor(x => x.Name).NotEmpty().MaximumLength(50);
        RuleFor(x => x.Age).InclusiveBetween(0, 150);
    }
}

// Program.cs
builder.Services.AddValidatorsFromAssemblyContaining<CreateUserRequestValidator>();

// UsersController.cs
public sealed class UsersController(
    UserService users,
    IValidator<CreateUserRequest> validator) : ControllerBase
{
    [HttpPost]
    public async Task<IActionResult> Create(CreateUserRequest request, CancellationToken ct)
    {
        var result = await validator.ValidateAsync(request, ct);
        if (!result.IsValid)
        {
            return ValidationProblem(new ValidationProblemDetails(result.ToDictionary()));
        }

        var id = await users.CreateAsync(request, ct);
        return Created($"/users/{id}", new { id });
    }
}

public CreateUserRequestValidator()
{
    RuleLevelCascadeMode = CascadeMode.Stop;

    RuleFor(x => x.Email).NotEmpty().EmailAddress();
    RuleFor(x => x.Name).NotEmpty().MaximumLength(50);
    RuleFor(x => x.Age).InclusiveBetween(0, 150);
}
